# -*- coding: utf-8 -*- """ ربات چت و آشنایی ناشناس (کاملاً رایگان - نسخه‌ی SQLite) ----------------------------------------------------------- مدل دسترسی: - ۲ هفته اول کاملاً رایگان و نامحدود - بعد از آن: دعوت ۴ نفر → دسترسی همیشگی، یا بدون دعوت → ۱۵ دقیقه چت در روز - غیرفعالی ۱ ماهه → پاک‌سازی خودکار اطلاعات پروفایل - مسدودی به‌خاطر گزارش تایید شده → ۲ روز فرصت برای رفع مسدودی با دعوت ۳ نفر، وگرنه اطلاعات پروفایل پاک می‌شود (ولی امکان رفع مسدودی همیشه باقی می‌ماند) نصب پیش‌نیاز: pip install python-telegram-bot --upgrade متغیرهای محیطی لازم قبل از اجرا: BOT_TOKEN -> از @BotFather می‌گیری ADMIN_IDS -> آیدی عددی تلگرام ادمین‌ها، با کاما جدا شده (مثال: 111111,222222) اجرا: python bot.py """ import logging import os import re import sqlite3 import time from contextlib import closing from datetime import datetime, timedelta, timezone from telegram import InlineKeyboardButton, InlineKeyboardMarkup, Update from telegram.ext import ( Application, CallbackQueryHandler, CommandHandler, ContextTypes, MessageHandler, filters, ) # --------------------------------------------------------------------------- # تنظیمات # --------------------------------------------------------------------------- BOT_TOKEN = os.environ.get("BOT_TOKEN", "توکن-ربات-تلگرام-اینجا") DB_PATH = os.environ.get("DB_PATH", "bot.db") ADMIN_IDS = { int(x) for x in os.environ.get("ADMIN_IDS", "").replace(" ", "").split(",") if x.isdigit() } TRIAL_DAYS = 14 DAILY_FREE_SECONDS = 15 * 60 INACTIVITY_PURGE_DAYS = 30 BAN_GRACE_DAYS = 2 REFERRALS_FOR_LIFETIME = 4 REFERRALS_FOR_UNBAN = 3 logging.basicConfig( format="%(asctime)s - %(name)s - %(levelname)s - %(message)s", level=logging.INFO, ) logger = logging.getLogger(__name__) def now_utc() -> datetime: return datetime.now(timezone.utc) PROVINCES = [ "آذربایجان شرقی", "آذربایجان غربی", "اردبیل", "اصفهان", "البرز", "ایلام", "بوشهر", "تهران", "چهارمحال و بختیاری", "خراسان جنوبی", "خراسان رضوی", "خراسان شمالی", "خوزستان", "زنجان", "سمنان", "سیستان و بلوچستان", "فارس", "قزوین", "قم", "کردستان", "کرمان", "کرمانشاه", "کهگیلویه و بویراحمد", "گلستان", "گیلان", "لرستان", "مازندران", "مرکزی", "هرمزگان", "همدان", "یزد", ] GENDER_LABEL = {"male": "پسر 👦", "female": "دختر 👧"} # فقط لینک/آیدی/دامنه تلگرام و وب رو فیلتر می‌کنه (اشتباه تایپی A-C قبلی هم اصلاح شد) SPAM_REGEX = re.compile( r"(@[a-zA-Z0-9_]{5,32})|(https?://\S+)|(www\.\S+)|(t\.me/\S+)|(telegram\.me/\S+)", re.IGNORECASE, ) # --- حافظه‌ی موقتِ زمان اجرا (نیازی به ماندگاری ندارن) --- PENDING_REG: dict[int, dict] = {} # مراحل ثبت‌نام/انتخاب زبان WAITING_QUEUE: list[int] = [] # صف اتصال تصادفی ACTIVE_CHATS: dict[int, int] = {} # {user_id: partner_id} CHAT_START: dict[int, datetime] = {} # زمان شروع چت فعلی هر کاربر RATE_LIMIT: dict[int, list[float]] = {} # ضدِ اسپم پیام SEARCH_RESULTS: dict[int, list] = {} # --------------------------------------------------------------------------- # دیتابیس # --------------------------------------------------------------------------- def db(): conn = sqlite3.connect(DB_PATH) conn.row_factory = sqlite3.Row return conn def init_db(): with closing(db()) as conn, conn: conn.execute( """ CREATE TABLE IF NOT EXISTS users ( user_id INTEGER PRIMARY KEY, name TEXT, gender TEXT, age INTEGER, province TEXT, city TEXT, language TEXT DEFAULT 'fa', created_at TEXT, last_active_at TEXT, referred_by INTEGER, referral_count INTEGER DEFAULT 0, is_premium_lifetime INTEGER DEFAULT 0, daily_chat_seconds_used INTEGER DEFAULT 0, last_chat_reset_date TEXT ) """ ) conn.execute( """ CREATE TABLE IF NOT EXISTS bans ( user_id INTEGER PRIMARY KEY, banned_at TEXT, unban_referral_count INTEGER DEFAULT 0, is_data_purged INTEGER DEFAULT 0 ) """ ) conn.execute( """ CREATE TABLE IF NOT EXISTS reports ( id INTEGER PRIMARY KEY AUTOINCREMENT, reporter_id INTEGER, reported_id INTEGER, reason TEXT DEFAULT 'گزارش از چت', status TEXT DEFAULT 'pending', created_at TEXT ) """ ) conn.execute( """ CREATE TABLE IF NOT EXISTS likes ( liker_id INTEGER, liked_id INTEGER, PRIMARY KEY (liker_id, liked_id) ) """ ) # --------------------------------------------------------------------------- # توابع کاربر # --------------------------------------------------------------------------- def get_user(
